import { OrientationValue } from '@game-studio/device';
// import { ArcadeTypes } from '@game-studio/shell-connection-types';

import { gameConfig } from './config-model';
import { inversifyContainer, } from '../inversify/container';
import { sessionDataModel } from '../models/session-data';
import { userModel } from '../models/user';
import { userPreferences } from '../models/user-preferences';
import { device } from '../services/device';
import { IBaseMetricLog } from '../types';
import { Verbosity } from '@game-studio/logging';
import { queryStringParams } from '../services/query-string';
import { CompanionPanel } from './companion-state';

// TODO: Add logging for all User Preferences - OneHandedPlay, ChatColour, ChatRoom, etc...
export interface IMetricLog extends IBaseMetricLog {
    /** Logged true when user clicks confirm on the auto-purchase popup */
    AUTO_PLAY_STARTED?: boolean;
    /** Logged true when a user opens the PayTable view for the first time each session */
    PAY_TABLE_VIEWED?: boolean;
    /** Logged at the end of a Game: true when the game was bought into with the swipe-to-buy feature */
    SWIPE_TO_BUY_PURCHASE?: boolean;
    /** Logged at the end of a Game: true when the game was bought into through auto-purchase */
    AUTO_BUY_PURCHASE?: boolean;
    /** Logged at the end of a Game: true when ColourBlind mode is on at the time the game ends */
    COLOUR_BLIND_MODE_ON?: boolean;
    /** Logged at the end of a Game: true when the user plays the game manually (such as clicking directly on a scratch panal) */
    MANUAL_PLAY_STYLE_USED?: boolean;
    /** Logged at the end of a Game: true when the user activates an auto-play feature (such as hold to Pop) */
    AUTO_PLAY_STYLE_USED?: boolean;
    /** Logged at the end of a Game: logs how the player first interacts with the game */
    FIRST_PLAY_STYLE?: string;
    /** Logged at the end of a Game: logs how the player last interacted with the game before it ended */
    LAST_PLAY_STYLE?: string;
    /** Logged at the end of a Game: logs the orientation of the device at the time the game ends */
    ORIENTATION?: OrientationValue;
    /** Logged at the end of a Game: contains a list of all gamePrefs and their values at the time the game ends */
    GAME_PREFERENCES?: object;
    /** Logged at the end of a Game: logs if the client is running WebGL or has fallen back to Canvas */
    WEBGL_OR_CANVAS?: string;
    /** Logged at the end of a Game: logs the active panel at the time the game ends */
    ACTIVE_PANEL?: CompanionPanel;
}

export class LoggingModel {
    public static get Instance(): LoggingModel { return this._instance || (this._instance = new LoggingModel()); }
    private static _instance: LoggingModel;

    public gameTime: number | undefined = undefined;
    public hasViewedHTP: boolean = false;
    public rendererType: string;

    private _initialiseTime: number = -1;
    private _assetChunkStartTime: number | undefined;
    private _loadTime: number | undefined;
    private _cachePercentage: number| undefined;
    private _assetChunkLoadTime: number | undefined;

    private _swipeToBuyPurchase: boolean = false;
    private _shouldLogSwipeToBuy: boolean = false;
    private _autoBuyPurchase: boolean = false;
    private _shouldLogAutoBuy: boolean = false;

    private _activePanel: CompanionPanel = null;
    private _shouldLogActivePanel: boolean = false;

    public set swipeToBuyPurchase(value: boolean) {
        this._swipeToBuyPurchase = value;
        this._shouldLogSwipeToBuy = true;
    }

    public set autoBuyPurchase(value: boolean) {
        this._autoBuyPurchase = value;
        this._shouldLogAutoBuy = true;
    }

    public set activePanel(value: CompanionPanel) {
        this._activePanel = value;
        this._shouldLogActivePanel = true;
    }

    private _firstPlayStyle: string | undefined = undefined;
    private _lastPlayStyle: string | undefined = undefined;

    private _manualPlayUsed: boolean = false;
    private _shouldLogManualPlayUsed: boolean = false;
    private _autoPlayUsed: boolean = false;
    private _shouldLogAutoPlayUsed: boolean = false;

    private _trackedErrors: string[] = [];

    public set manualPlayUsed(value: boolean) {
        this._manualPlayUsed = value;
        this._shouldLogManualPlayUsed = true;
    }

    public set autoPlayUsed(value: boolean) {
        this._autoPlayUsed = value;
        this._shouldLogAutoPlayUsed = true;
    }

    private constructor() { 
        window.addEventListener('visibilitychange', this.clearInitialiseTime.bind(this));
    }

    /**
     * Updates the lastPlayStyle with the new style, only updates firstPlayStyle if it has not yet been assigned too.
     * @param newStyle string representing the new playstyle
     */
    public updatePlayStyle(newStyle: string): void {
        if (!this._firstPlayStyle) {
            this._firstPlayStyle = newStyle;
        }
        this._lastPlayStyle = newStyle;
    }

    /**
     * Sends a metric log with the properties provided
     * @param props An IMetricLog with properties defined to append to the log.
     */
    public logMetrics(props: IMetricLog): void {
        loggingModel.sendMetric('DEBUG1', `${gameConfig.loggingName} Metrics`, props, `${gameConfig.loggingName}:${queryStringParams.currentSkin}`);
    }

    /**
     * Sends a metric log detailing the state of this game
     * @param props An IMetricLog which can define additional data to add to the log
     */
    public logEndGameMetrics(props?: IMetricLog): void {
        const values: IMetricLog = {
            FIRST_PLAY_STYLE: this._firstPlayStyle,
            LAST_PLAY_STYLE: this._lastPlayStyle,

            ORIENTATION: device.orientation.value,

            SOUND_PREFERENCE: userPreferences.sound || false,
            MUSIC_PREFERENCE: userPreferences.music || false,

            GAME_PREFERENCES: userPreferences.gamePrefValues,

            WEBGL_OR_CANVAS: this.rendererType
        };

        if (this._shouldLogSwipeToBuy) {
            values.SWIPE_TO_BUY_PURCHASE = this._swipeToBuyPurchase;
        }
        if (this._shouldLogAutoBuy) {
            values.AUTO_BUY_PURCHASE = this._autoBuyPurchase;
        }

        if (this._shouldLogManualPlayUsed) {
            values.MANUAL_PLAY_STYLE_USED = this._manualPlayUsed;
        }
        if (this._shouldLogAutoPlayUsed) {
            values.AUTO_PLAY_STYLE_USED = this._autoPlayUsed;
        }

        if (this._shouldLogActivePanel) {
            values.ACTIVE_PANEL = this._activePanel;
        }

        if (this.gameTime) {
            values.GAME_TIME = this.gameTime;
        }

        if (this._loadTime) {
            values.LOAD_TIME = this._loadTime;
            values.DEVICE_MODEL = device.model.model;
            values.DEVICE_VENDOR = device.model.vendor;
            this._loadTime = undefined;
        }

        if (this._cachePercentage) {
            values.CACHE_HIT_PERCENTAGE = this._cachePercentage;
            this._cachePercentage = undefined;
        }

        if (this._assetChunkLoadTime) {
            values.ASSET_LOAD_TIME = this._assetChunkLoadTime;
            this._assetChunkLoadTime = undefined;
        }

        if (gameConfig.features.colourBlindMode) {
            values.COLOUR_BLIND_MODE_ON = userPreferences.colourBlindMode;
        }

        if (props) {
            Object.assign(values, props);
        }

        loggingModel.sendMetric('DEBUG1', `${gameConfig.loggingName} Game Data`, values, `${gameConfig.loggingName}:${queryStringParams.currentSkin}`);
        // TODO: confirm this can be removed, was app specific logging
        // inversifyContainer.frameConnection.logAnalytics({
        //     event: 'game-complete',
        //     stake: inversifyContainer.stake.currentStake,
        //     payout: inversifyContainer.gameModel.payout
        // });

        this.reset();
    }

    /**
     * Logs an exception in our backend via the frameConnection interface
     * @param message The message to log in the error
     */
    public logException(message: string): void {
        this.sendLog('ERROR', message, `${gameConfig.loggingName}:${queryStringParams.currentSkin}`);
    }

    public sendLog(verbosity: Verbosity, message: string, gameName?: string): Promise<void> {
        const logData = inversifyContainer.CreateLogBody(verbosity, 'exception', gameName, message);

        fetch(logData.URL, {
            method: 'POST',
            body: JSON.stringify([logData.body]),
            headers: logData.headers
        });

        return Promise.resolve();
    }

    public sendMetric(verbosity: Verbosity, name: string, value: IBaseMetricLog, gameName?: string): Promise<void> {
        const logData = inversifyContainer.CreateLogBody(verbosity, 'metric', gameName);

        Object.assign(logData.body, value);

        fetch(logData.URL, {
            method: 'POST',
            body: JSON.stringify([logData.body]),
            headers: logData.headers
        });

        return Promise.resolve();
    }

    public trackError(message: string): void {
        if (this._trackedErrors.length < gameConfig.errorsToTrack) {
            this._trackedErrors.push(message);
        }
    }

    public getErrors(): string[] {
        return this._trackedErrors;
    }

    public clearErrors(): void {
        this._trackedErrors = [];
    }

    /**
     * Resets the model to default values ready for the next game
     */
    private reset(): void {
        this.gameTime = undefined;

        this._swipeToBuyPurchase = false;
        this._shouldLogSwipeToBuy = false;
        this._autoBuyPurchase = false;
        this._shouldLogAutoBuy = false;

        this._firstPlayStyle = undefined;
        this._lastPlayStyle = undefined;

        this._manualPlayUsed = false;
        this._shouldLogManualPlayUsed = false;
        this._autoPlayUsed = false;
        this._shouldLogAutoPlayUsed = false;
    }

    public recordStartTime(): void {
        this._initialiseTime = new Date().getTime();
        this._assetChunkStartTime = this._initialiseTime;
    }

    public recordAssetChunkStartTime(): void {
        if (this._assetChunkStartTime !== undefined) { return; }
        this._assetChunkStartTime = new Date().getTime();
    }

    public recordAssetChunkEndTime(): void {
        if (this._assetChunkStartTime === undefined) { return; }

        if (this._assetChunkLoadTime === undefined) {
            this._assetChunkLoadTime = 0;
        }
        
        this._assetChunkLoadTime += new Date().getTime() - this._assetChunkStartTime;
        this._assetChunkStartTime = undefined;
    }

    public clearInitialiseTime(): void {
        this._initialiseTime = -1;
    }

    public recordLoadEndTime(): void {
        if (this._initialiseTime !== -1) {
            this._loadTime = new Date().getTime() - this._initialiseTime;

            if (this._loadTime < 0) {
                this._loadTime = undefined;
                return;
            }

            const resources = performance.getEntriesByType('resource');

            let cacheHit: number = 0;
            let cacheMiss: number = 0;

            resources.forEach((resource) => {
                if (!(resource.name.endsWith('.js') || resource.name.endsWith('.html') || resource.name.endsWith('resume') || resource.name.includes('featuretoggle'))) {
                    if (resource.duration <= 100) {//using duration, its not perfect, i would have liked to use transfertime but on some devices I was always getting 0
                        cacheHit++;
                    } else {
                        cacheMiss++;
                    }
                }
            });

            this._cachePercentage = Math.ceil(cacheHit / (cacheHit + cacheMiss) * 100);
        }
    }

    public logBeginSession() :void {
        const logData = inversifyContainer.CreateLogBody(
            'INFO', 
            'session', 
            `${gameConfig.loggingName}:${queryStringParams.currentSkin}`, 
            `${gameConfig.loggingName}:${queryStringParams.currentSkin} session started`, 
            'platform'
        );

        const map = {
            eventName : 'sessionStarted',
            sessionId : sessionDataModel.getSessionToken(),
            clientTypeId : userModel.clientTypeId.toString()
        };

        Object.assign(logData.body, map);

        fetch(logData.URL, {
            method: 'POST',
            body: JSON.stringify([logData.body]),
            headers: logData.headers
        });
    }

    /**
     * Logs a custom event in our backend via the frameConnection interface
     * @param name The name of the event
     * @param data The data to log in the event
     */
    public logEvent(name: string, data: Record<string, string>): void {
        data = { ...data, ...{ EVENT_NAME: name, SESSION_ID: sessionDataModel.getSessionToken() } };
        loggingModel.sendMetric('INFO', name, data, `${gameConfig.loggingName}:${queryStringParams.currentSkin}`);
    }

    public logPurchaseEvent(eventName : string, message : string) : void {
        const logData = inversifyContainer.CreateLogBody(
            'INFO', 
            'session', 
            `${gameConfig.loggingName}:${queryStringParams.currentSkin}`, 
            `${gameConfig.loggingName}:${queryStringParams.currentSkin}:${eventName}`,
            'platform'
        );

        const map = {
            eventName : eventName,
            sessionId : sessionDataModel.getSessionToken(),
            clientTypeId : userModel.clientTypeId,
            purchaseMessage : message
        };

        Object.assign(logData.body, map);
        
        fetch(logData.URL, {
            method: 'POST',
            body: JSON.stringify([logData.body]),
            headers: logData.headers
        });
    }
}

export const loggingModel = LoggingModel.Instance;
